  const keys=[...new Set([...targetScope.matchAll(/\\?"key\\?"\s*:\s*\\?"(member_[0-9]+)/g)].map(match=>match[1]))];
  const scripted=responses.get(owner);if(scripted){scripted(res,raw,keys,ids);return;}
