 const f=await fixture(t),material=await f.publish(f.a,'A'),other=await f.publish(f.b,'B'),gate={entered:deferred(),release:deferred()};f.gates.set('A',gate);await f.submit(f.a,[material.id]);await gate.entered.promise;
