test('scoped raw coding groups and page budgets retain exact owner/source heads and bounded newest originals',async t=>{
 const f=await fixture(t),sourceId='generated-coding';for(const [user,label] of [[f.a,'A'],[f.b,'B']] as const){assert.equal((await f.request(user.token,'/api/ingress/sources','POST',{id:sourceId,name:'Generated coding',kind:'coding-agent',deviceId:'same-device',platform:'import',retention:'snapshot'})).statusCode,200);const items=[0,1,2].map(index=>({externalId:'event-'+index,revision:'v1',observedAt:new Date(Date.parse('2026-01-01T00:00:00Z')+index*1000).toISOString(),title:'Generated event',text:'GENERATED_CODING_'+label+'_'+index,kind:'message',layer:'original',document:{coding:{version:1,provider:'codex',sessionId:'same-session',projectKey:'same-project',eventId:'event-'+index,role:'assistant',attribution:'agent',channel:'final',part:0,parts:1}}}));assert.equal((await f.request(user.token,'/api/ingress/sources/'+sourceId+'/items','POST',{batchId:'same-batch',items})).statusCode,200);}const end=Date.now()+30000;for(const [user,label] of [[f.a,'A'],[f.b,'B']] as const){for(;;){const page=(await f.request(user.token,'/api/materials?kind=mote.coding-session')).json(),material=page.items[0];if(material?.memberCount===3){const data=await f.data(user),original=data.privateData.readMaterial(material.id);assert.ok(original.text.includes('GENERATED_CODING_'+label+'_0'));assert.ok(!original.text.includes('GENERATED_CODING_'+(label==='A'?'B':'A')));assert.equal(material.origin.sessionId,'same-session');break;}assert.ok(Date.now()<end,JSON.stringify(page));await delay(10);}}
 const deviceId='generated-budget-device',pageSource='ui-page:'+createHash('sha256').update(JSON.stringify(deviceId)).digest('hex');assert.equal((await f.request(f.a.token,'/api/ingress/sources','POST',{id:pageSource,name:'Generated page budget',kind:'custom',deviceId,platform:'android',retention:'snapshot'})).statusCode,200);const values=Array.from({length:64},(_,index)=>{const at=new Date(Date.parse('2026-01-01T00:00:00Z')+index*1000).toISOString(),page={version:2,scope:'visible_window',adapterId:'generated.budget',adapterVersion:'1',appVersion:'1',activity:'Generated.Article',status:'ok',truncated:false,observations:{firstAt:at,lastAt:at,count:1},objects:[{kind:'article',title:'Generated bounded article',body:Array.from({length:2},(_,paragraph)=>({text:'GENERATED_BUDGET_'+index+'_'+paragraph+'_'+String(index%10).repeat(31700)})),url:'https://fixture.invalid/budget',identity:{type:'url',value:'https://fixture.invalid/budget'}}]};return {id:randomUUID(),deviceId,deviceName:'Generated phone',platform:'android',source:'ui_page',appId:'generated.budget.app',appName:'Generated budget',capturedAt:at,durationMs:0,ocrText:uiPageText(page as any),privacy:{excluded:false,redacted:true,mode:'local',collection:'content'},metadata:{version:1,observedAt:at,collector:{method:'accessibility'},uiPage:page}};});const received=await f.request(f.a.token,'/api/ingress/sources/'+pageSource+'/captures','POST',{batchId:'budget',items:values});assert.equal(received.statusCode,200,received.body);for(;;){const page=(await f.request(f.a.token,'/api/materials?kind=mote.ui-page-object')).json(),material=page.items[0];if(material?.coverage.state==='partial'&&material.memberCount<64){const data=await f.data(f.a),original=data.privateData.readMaterial(material.id);assert.equal(material.coverage.state,'partial');assert.ok(material.fidelity.limitations.includes('ui_page_group_limit'));assert.ok(material.textLength<=4000000);assert.ok(!original.text.includes('GENERATED_BUDGET_0_'));const members=data.privateData.materialMembers(material.id,{offset:0,limit:200}).items;assert.equal(members.at(-1)!.ref,'capture:'+values[63].id);assert.ok(!members.some(member=>member.ref==='capture:'+values[0].id));break;}assert.ok(Date.now()<end,JSON.stringify(page));await delay(15);}assert.equal((await f.request(f.b.token,'/api/materials?kind=mote.ui-page-object')).json().items.length,0);assert.equal(f.requests.length,0,'structural organizers do not authorize new model calls');
});

test('owner job retry reuses immutable model/task checkpoints and job cursors cannot cross owners or page sizes',async t=>{
 const f=await fixture(t),material=await f.publish(f.a,'A');f.responses.set('A',res=>{res.statusCode=422;res.end('GENERATED_RETRY_FAILURE');});const job=await f.submit(f.a,[material.id]);assert.ok(['failed','blocked'].includes(await f.terminal(job.tasks.extract.id)));const before=(await f.request(f.a.token,'/api/memory/jobs/'+job.id)).json();assert.equal((await f.request(f.b.token,'/api/memory/jobs/'+job.id+'/retry','POST',{})).statusCode,404);f.responses.delete('A');const retried=await f.request(f.a.token,'/api/memory/jobs/'+job.id+'/retry','POST',{});assert.equal(retried.statusCode,200,retried.body);const complete=await f.wait(f.a,job.id);assert.equal(complete.tasks.extract.id,before.tasks.extract.id);assert.equal(complete.tasks.extract.attempts,1,'explicit M05 retry resets its attempt budget');assert.equal(f.requests.length,3,'one failed extraction then actual extraction and independent review');const second=await f.submit(f.a,[material.id]);await f.wait(f.a,second.id);const page=(await f.request(f.a.token,'/api/memory/jobs?limit=1')).json();assert.ok(page.nextCursor);assert.equal((await f.request(f.b.token,'/api/memory/jobs?limit=1&cursor='+encodeURIComponent(page.nextCursor))).statusCode,400);assert.equal((await f.request(f.a.token,'/api/memory/jobs?limit=2&cursor='+encodeURIComponent(page.nextCursor))).statusCode,400);const next=(await f.request(f.a.token,'/api/memory/jobs?limit=1&cursor='+encodeURIComponent(page.nextCursor))).json();assert.notEqual(next.items[0].id,page.items[0].id);assert.equal((await f.request(f.a.token,'/api/memories')).json().items.length,1,'retry and repeated extraction share the existing exact publisher');
});

test('Ask owner policy canonical lifecycle exports definitions, isolates equal IDs and restores no task authority',async t=>{
 const f=await fixture(t),id=randomUUID();for(const user of [f.a,f.b]){const response=await f.request(user.token,'/api/ask-automations','POST',{id,kind:'working'});assert.equal(response.statusCode,200,response.body);}
 const context=await f.node.authority.authenticate(f.a.token),archive=await f.node.services.forUser(context).exportUser('ask-automation'),beforeB=f.read(db=>db.prepare('SELECT * FROM ma_automations WHERE user_id=?').all(f.b.userId));assert.equal((archive.payload as any).activeAuthority,false);assert.equal((archive.payload as any).policies.length,1);assert.ok(!JSON.stringify(archive).includes('GENERATED_A_KEY'));const deleted=await(await f.lifecycle(f.a,'delete',randomUUID(),'ask-automation')).run();assert.equal(deleted.status,'complete');assert.deepEqual(f.read(db=>db.prepare('SELECT * FROM ma_automations WHERE user_id=?').all(f.b.userId)),beforeB);assert.equal(f.read(db=>db.prepare('SELECT count(*) n FROM ma_automations WHERE user_id=?').get(f.a.userId)!.n),0);
 const restore=await f.lifecycle(f.a,'restore',randomUUID(),'ask-automation');await restore.run(archive);await restore.run(archive);const restored=f.read(db=>db.prepare('SELECT state,task_id FROM ma_automations WHERE user_id=?').get(f.a.userId)!);assert.equal(restored.state,'restored');assert.equal(restored.task_id,null);await f.restart();await delay(100);assert.equal(f.requests.length,0,'data restore cannot schedule models or renew an old grant');const resumed=await f.request(f.a.token,'/api/ask-automations/'+id+'/resume','POST',{});assert.equal(resumed.statusCode,409,'restored definitions require an explicit fresh admission');const reauthorized=await f.request(f.a.token,'/api/ask-automations','POST',{id,kind:'working'});assert.equal(reauthorized.statusCode,200,reauthorized.body);assert.equal(reauthorized.json().state,'active');assert.ok(reauthorized.json().task_id);assert.equal(f.requests.length,0);const other=await f.request(f.b.token,'/api/ask-automations/'+id);assert.equal(other.statusCode,200);assert.equal(other.json().generation,(beforeB[0] as any).generation);
});

test('representative A keeps long declared Coding dialogue through real M03 M06 extraction and independent Memory review',async t=>{
 const f=await fixture(t),selected:any[]=[];for(const [user,label] of [[f.a,'A'],[f.b,'B']] as const){await f.replace(user.token,'processing',{...defaultProcessingSettings(),automatic:true,understandingEnabled:false});await f.request(user.token,'/api/ingress/sources','POST',{id:'same-coding',name:'Generated coding',kind:'coding-agent',deviceId:'same-device',platform:'import',retention:'archive'});const message=(id:string,body:string,coding:Record<string,unknown>)=>({externalId:id,revision:'same-revision',observedAt:'2026-01-01T00:00:00Z',title:'Generated Coding',text:body,kind:'message',layer:'original',document:{coding:{version:1,provider:'codex',sessionId:'same-session',projectKey:'same-project',eventId:id,part:0,parts:1,...coding}}}),human=text(label)+'\n'+label.repeat(11000)+'\nGENERATED_LONG_TAIL_'+label,items=[message('same-tool','GENERATED_ARCHIVED_TOOL_BYTES',{role:'tool_result'}),message('same-human','<environment_context>GENERATED_HOST_ONLY</environment_context>\n'+human,{role:'user',attribution:'human'})],received=await f.request(user.token,'/api/ingress/sources/same-coding/items','POST',{batchId:'same-batch',items});assert.equal(received.statusCode,200,received.body);const receipts=received.json().captures;const deadline=Date.now()+15000;let material:any;for(;;){const state=await f.request(user.token,'/api/processing/originals/'+receipts[1].original.ref.slice(9));if(state.json().indexed){material=state.json().materialId;break;}assert.ok(Date.now()<deadline,state.body);await delay(10);}const opened=await f.request(user.token,'/api/materials/'+material+'/read?length=4096');assert.equal(opened.statusCode,200,opened.body);assert.ok(opened.json().text.includes(text(label)),opened.body);let offset=opened.json().textRange.nextOffset;let all=opened.json().text;while(offset!==null){const page=(await f.request(user.token,'/api/materials/'+material+'/read?length=4096&offset='+offset)).json();all+=page.text;offset=page.textRange.nextOffset;}assert.ok(all.endsWith('GENERATED_LONG_TAIL_'+label));assert.ok(!all.includes('GENERATED_HOST_ONLY'));const context=await f.node.authority.authenticate(user.token),source=f.node.ingress.bindSource(context,['same-coding'],()=>{});assert.equal(JSON.parse(source.readOriginal(receipts[0].original.ref).bytes.toString()).text,items[0].text);assert.equal((await f.request(user.token,'/api/data/search?query=GENERATED_ARCHIVED_TOOL_BYTES')).json().items.length,0);selected.push({user,label,material});f.answers.set(label,(raw,keys,ids)=>{const id=ids.find(id=>f.read(db=>String(db.prepare('SELECT json FROM mm_evidence WHERE user_id=? AND id=?').get(user.userId,id)?.json??'').includes(text(label))));if(!id)return {memories:[],coverage:keys.map(key=>({key,state:'no_candidates',candidateIndexes:[]}))};return {memories:[{title:'Generated dialogue '+label,statement:'Nora prefers generated tea. ['+id+']',uncertainty:'Declared third-party fixture dialogue only',admission:{layer:'memory',reason:'Explicit fixture statement',scope:'Nora in generated fixture',attribution:'third_party'},evidenceIds:[id],evidence:[{id,quote:text(label)}]}],coverage:keys.map((key,index)=>({key,state:index===0?'checked':'no_candidates',candidateIndexes:index===0?[0]:[]}))};});}
 for(const {user,material} of selected)await f.wait(user,(await f.submit(user,[material])).id);for(const {user,label} of selected){assert.ok((await f.request(user.token,'/api/memories')).json().items.length>0);const calls=f.requests.filter(call=>call.key.includes('_'+label+'_'));assert.ok(calls.some(call=>call.raw.includes('GENERATED_LONG_TAIL_'+label)));assert.ok(calls.every(call=>!call.raw.includes('GENERATED_ARCHIVED_TOOL_BYTES')&&!call.raw.includes('GENERATED_HOST_ONLY')&&!call.raw.includes(text(label==='A'?'B':'A'))));}
});
